import{_ as s,o as a,c as i,a0 as t}from"./chunks/framework.DYAX5gPL.js";const y=JSON.parse('{"title":"Analysis","description":"","frontmatter":{"title":"Analysis"},"headers":[],"relativePath":"en/api/analysis.md","filePath":"en/api/analysis.md"}'),l={name:"en/api/analysis.md"};function r(n,e,d,o,u,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="analysis" tabindex="-1">Analysis <a class="header-anchor" href="#analysis" aria-label="Permalink to &quot;Analysis&quot;">​</a></h1><p>Analysis is the base class of 3D spatial analysis, defining methods common to all kinds of 3D spatial analysis.</p><p>Analysis can only be added to a GroupGLLayer; it cannot be added to other WebGL layers.</p><blockquote><p>Note: In the 2026 source, the subclasses of Analysis include CutAnalysis (section cut), ViewshedAnalysis (viewshed), SkylineAnalysis (skyline), FloodAnalysis (flood), InSightAnalysis (intervisibility), CrossCutAnalysis (cross-section) and HeightLimitAnalysis (height limit, inheriting from FloodAnalysis). ExcavateAnalysis (excavation) does not inherit from Analysis; it inherits ExtrudePolygonLayer from <code>@maptalks/vt</code>, so it is out of scope for this page (verified 2026).</p></blockquote><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><details><summary>addTo(groupGLLayer)</summary><div><br><p>Adds the analysis object to a GroupGLLayer.</p><p>Spatial analysis objects can only be added to a GroupGLLayer; they cannot be added to other WebGL layers.</p><p>Parameters:</p><ul><li>groupGLLayer <strong>GroupGLLayer</strong> the GroupGLLayer</li></ul><p>Returns:</p><ul><li>this</li></ul></div></details><details><summary>remove()</summary><div><br><p>Removes the spatial analysis object from the layer.</p><p>Returns:</p><ul><li>void</li></ul></div></details><details><summary>update(name, value)</summary><div><br><p>Updates options data.</p><p>Parameters:</p><ul><li>name <strong>String</strong> the setting name</li><li>value <strong>any</strong> the setting value</li></ul><p>Returns:</p><ul><li>void</li></ul></div></details><details><summary>getAnalysisType()</summary><div><br><p>Gets the type of the Analysis.</p><p>Returns:</p><ul><li>String</li></ul></div></details><details><summary>getDefines()</summary><div><br><p>Internal method.</p><p>Returns the defines added to the shader when the Analysis is rendered.</p><p>Returns:</p><ul><li>Object</li></ul></div></details><details><summary>renderAnalysis(meshes)</summary><div><br><p>Internal method.</p><p>Renders the spatial analysis scene (implemented by each analysis subclass) and returns the uniform variables required for rendering.</p><p>Parameters:</p><ul><li>meshes <strong>Mesh[]</strong> the scene meshes</li></ul><p>Returns:</p><ul><li>Object</li></ul></div></details><details><summary>enable()</summary><div><br><p>Enables the analysis.</p><p>Returns:</p><ul><li>void</li></ul></div></details><details><summary>disable()</summary><div><br><p>Disables the analysis.</p><p>Returns:</p><ul><li>void</li></ul></div></details><details><summary>isEnable()</summary><div><br><p>Whether the analysis is enabled.</p><p>Returns:</p><ul><li>Boolean</li></ul></div></details><details><summary>getExcludeLayers()</summary><div><br><p>Gets the list of layer ids excluded from the analysis (these layers are ignored during the analysis).</p><p>Returns:</p><ul><li>String[]</li></ul></div></details><details><summary>setExcludeLayers(layerIds)</summary><div><br><p>Sets the list of layer ids excluded from the analysis.</p><p>Parameters:</p><ul><li>layerIds <strong>String[]</strong> list of layer ids</li></ul><p>Returns:</p><ul><li>void</li></ul></div></details><details><summary>exportAnalysisMap(meshes)</summary><div><br><p>Exports the analysis result image (RGBA pixel data); returns null when the analysis is not enabled.</p><p>Parameters:</p><ul><li>meshes <strong>Mesh[]</strong> the scene meshes</li></ul><p>Returns:</p><ul><li>Uint8Array</li></ul></div></details><blockquote><p>This document has been cross-checked against the @maptalks/gl-layers 2026 source (api-notes-others.md / api-notes-vt-gl.md)</p></blockquote>',18)])])}const h=s(l,[["render",r]]);export{y as __pageData,h as default};
